//#region src/lib/podman-spawn.ts
const execFileAsync = promisify(execFile);
async function execPodman(args) {
	const { stdout } = await execFileAsync("podman", args);
	return stdout;
}
async function execPodmanStreaming(args) {
	await Process.spawn(["podman", ...args], {
		stdin: 1,
		stdout: 2,
		stderr: 2
	}).waitOrThrow();
}
async function execPodmanStreamingWithStdoutLines(args, onLine) {
	const proc = Process.spawn(["podman", ...args], {
		stdin: 0,
		stdout: 4,
		stderr: 4
	});
	const rl = createInterface({
		input: proc.stdout,
		crlfDelay: Infinity
	});
	rl.on("line", onLine);
	try {
		await proc.waitOrThrow();
	} finally {
		rl.close();
	}
}
